algorithms.pseudocode:
function fold(x: uint, k: int) -> uint:
    // XOR of the successive k-bit chunks of x
    folded = 0
    while x != 0:
        folded = folded ^ (x & ((1 << k) - 1))
        x = x >> k
    return folded

function sat_update(ctr: int, up: bool, bits: int):
    // Signed saturating counter in [-2^(bits-1), 2^(bits-1) - 1], moved by one step
    if up:
        if ctr < (1 << (bits - 1)) - 1:
            ctr = ctr + 1
    else:
        if ctr > -(1 << (bits - 1)):
            ctr = ctr - 1

function ut_idx(t: int, pc: uint64) -> uint:
    // One index per table per bank, from the PC only; Figure 5c draws it as PC skewed
    return (pc ^ (pc >> (3 * (t + 1)))) & (ut_entries - 1)

function wt_idx(t: int, pc: uint64, d: uint) -> uint:
    // Figure 5c draws it as PC + reg. digest
    n = (t == 0) ? wt0_entries : ((t == 1) ? wt1_entries : wt2_entries)
    k = log2(n)
    return (pc ^ (pc >> k) ^ fold(d, k)) & (n - 1)

function generate_digest(val: uint64, reg_type: enum {INT, FP, FLAG}) -> uint:
    // Figure 6: build the paper's 12-bit digest, then fold it to digest_width bits
    if reg_type == INT:
        // Figure 6a: Value[5:0] at [11:6], leading count at [8:3], trailing count at [5:0], XORed together
        low6 = val & 0x3F
        lead_bit = (val >> 63) & 1
        lead_count = min(count_leading(val, lead_bit), 63)
        trail_bit = val & 1
        trail_count = min(count_trailing(val, trail_bit), 63)
        raw = ((low6 << 6) ^ (lead_count << 3) ^ trail_count) & 0xFFF
    else if reg_type == FP:
        // Figure 6b: the format comes from the most significant bits, see U5; fields are right-aligned
        if (val >> 32) != 0:
            raw = (val >> 55) & 0x1FF
        else if (val >> 16) != 0:
            raw = (val >> 26) & 0x3F
        else:
            raw = (val >> 13) & 0x7
    else:
        // Figure 6c: the four flag bits, replicated three times
        flag4 = val & 0xF
        raw = (flag4 << 8) | (flag4 << 4) | flag4
    return fold(raw, digest_width)

function on_instruction_decode(dest_reg: int, rob_tag: uint):
    // 1. Age every valid digest by one decoded instruction
    for r in 0 .. 64:
        if register_status_table[r].valid == 1:
            if register_status_table[r].decay_ctr == 0:
                register_status_table[r].valid = 0
            else:
                register_status_table[r].decay_ctr = register_status_table[r].decay_ctr - 1
    // 2. Claim the destination for this instruction
    if dest_reg >= 0 and dest_reg <= 64:
        register_status_table[dest_reg].valid = 0
        register_status_table[dest_reg].payload = rob_tag & ((1 << rob_tag_bits) - 1)
        register_status_table[dest_reg].decay_ctr = 0

function on_instruction_writeback(dest_reg: int, rob_tag: uint, val: uint64, reg_type: enum {INT, FP, FLAG}):
    if dest_reg >= 0 and dest_reg <= 64:
        tag = rob_tag & ((1 << rob_tag_bits) - 1)
        // Only the youngest decoded writer of dest_reg may deposit its digest
        if register_status_table[dest_reg].valid == 0 and register_status_table[dest_reg].payload == tag:
            register_status_table[dest_reg].payload = generate_digest(val, reg_type)
            register_status_table[dest_reg].decay_ctr = decay_interval - 1
            register_status_table[dest_reg].valid = 1

function snapshot_status_table() -> array[65] of {valid: bit, digest: uint}:
    snap = [{valid: 0, digest: 0} for r in 0 .. 64]
    for r in 0 .. 64:
        snap[r].valid = register_status_table[r].valid
        snap[r].digest = register_status_table[r].payload & ((1 << digest_width) - 1)
    return snap

function predict(pc: uint64, snap: array[65] of {valid: bit, digest: uint}) -> (int, array[num_banks] of int):
    sr_total = 0
    for b in 0 .. num_banks - 1:
        // Bank b holds registers b, b + num_banks, b + 2 * num_banks, ... up to 64
        best_reg = -1
        max_useful = 0
        for r in b .. 64 step num_banks:
            if snap[r].valid == 1:
                s = r / num_banks
                useful_sum = 0
                for t in 0 .. 2:
                    u = ut_idx(t, pc)
                    useful_sum = useful_sum + usefulness_weight_tables[b][t][u][s]
                // Strict comparison: on a tie the lower register id is kept
                if best_reg < 0 or useful_sum > max_useful:
                    max_useful = useful_sum
                    best_reg = r
        bank_contrib[b] = 0
        // Figure 5c: the bank's vote is scaled by x0 or x2.5, chosen by the largest usefulness
        if best_reg >= 0 and max_useful >= usefulness_threshold:
            d = snap[best_reg].digest
            p = 0
            for t in 0 .. 2:
                w = wt_idx(t, pc, d)
                p = p + (2 * prediction_weight_tables[b][t][w] + 1)
            bank_contrib[b] = trunc(p * multiplier_useful)
        sr_total = sr_total + bank_contrib[b]
    return (sr_total, bank_contrib)

function update(pc: uint64, taken: bool, lsum: int, snap: array[65] of {valid: bit, digest: uint}, bank_contrib: array[num_banks] of int):
    for b in 0 .. num_banks - 1:
        // Train only registers that were available at prediction time
        avail = [r for r in b .. 64 step num_banks if snap[r].valid == 1]
        if length(avail) == 0:
            continue
        // One register per bank, chosen at random: a single write port per table
        r_train = avail[prng_next() % length(avail)]
        s = r_train / num_banks
        d = snap[r_train].digest
        // The trained register's vote, read before any counter moves
        p = 0
        for t in 0 .. 2:
            w = wt_idx(t, pc, d)
            p = p + (2 * prediction_weight_tables[b][t][w] + 1)
        // Usefulness learns only when x0 versus x multiplier_useful flips the sign of LSUM
        rest = lsum - bank_contrib[b]
        if ((rest + trunc(p * multiplier_useful)) >= 0) != (rest >= 0):
            for t in 0 .. 2:
                u = ut_idx(t, pc)
                sat_update(usefulness_weight_tables[b][t][u][s], (p >= 0) == taken, ut_ctr_bits)
        // Weights move toward the outcome
        for t in 0 .. 2:
            w = wt_idx(t, pc, d)
            sat_update(prediction_weight_tables[b][t][w], taken, wt_ctr_bits)

function on_mispredict_recovery(flushed_rob_tags: set[uint]):
    for r in 0 .. 64:
        // An entry still waiting on a flushed instruction is reset; completed digests survive
        if register_status_table[r].valid == 0 and (register_status_table[r].payload in flushed_rob_tags):
            register_status_table[r].payload = 0
            register_status_table[r].decay_ctr = 0
